using System;
using System.Linq;
using System.Collections.Generic;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
using Ability=Polytopia.Data.UnitAbility.Type;
namespace Deception.Tests
{
 public static class RogueCombatTests
 {
  static readonly List<string> Tests=new();static int Assertions;
  static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}
  static void Test(string id,Action body){try{NativeRogueRules.Clear();NativeRegroupSession.Owned.Clear();NativeGameStateEnvelope.Values.Clear();Fault.At="";Harness.Reset();body();Tests.Add(id);}catch(Exception e){throw new Exception(id,e);}}
  static TileData Tile(GameState s,int x,int y)=>MapDataExtensions.GetTile(s.Map,new(x,y))!;
  static UnitState Unit(GameState s,uint id){s.TryGetUnit(id,out var u);return u!;}
  static NativeIdentityLedger Read(GameState s){var p=NativeGameStateEnvelope.Get(s)!;return NativeIdentityLedgerCodec.Decode(p.Bytes(),p.Revision);}
  static void Write(GameState s,NativeIdentityLedger ledger){var p=NativeGameStateEnvelope.Get(s);long r=p?.Revision??0;NativeGameStateEnvelope.Set(s,r,NativeIdentityLedgerCodec.Encode(ledger,r));}
  static GameState Make(bool sourceRogue=true,bool targetRogue=true,byte targetOwner=1)
  {
   var s=new GameState();s.Map.Tiles.Values=(from y in Enumerable.Range(0,4)from x in Enumerable.Range(0,5)select new TileData{coordinates=new(x,y)}).ToArray();
   foreach(byte p in new byte[]{1,2,3}){s.PlayerStates.Add(new(){Id=p});foreach(var t in s.Map.Tiles.Values)t.explorers.Add(p);}
   Tile(s,1,1).unit=new(){id=1,owner=1,type=UnitType.polytar,coordinates=new(1,1),UnitData=new(){attack=30,defence=10}};
   Tile(s,2,1).unit=new(){id=2,owner=targetOwner,type=UnitType.dcp_spy,coordinates=new(2,1),UnitData=new(){attack=0,defence=10}};
   Tile(s,2,2).unit=new(){id=3,owner=1,coordinates=new(2,2)};
   var rows=s.Map.Tiles.Values.Where(t=>t.unit is not null).Select(t=>new LedgerUnit(t.unit!.id,t.unit.id,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,8,Rogue:t.unit.id==1&&sourceRogue?new(2,1,4):t.unit.id==2&&targetRogue?new(3,targetOwner,4):null)).ToArray();
   Write(s,new(Guid.Parse("4ee06133-e62d-44fa-a966-28a9653b3612"),100,1,rows,Array.Empty<LedgerReceipt>()));NativeRegroupSession.Owned.Add(s);return s;
  }
  static AttackCommand Command(GameState s)=>new(){PlayerId=1,UnitId=1,Origin=Unit(s,1).coordinates,Target=Unit(s,2).coordinates};
  static bool Protection(GameState s,UnitState u,byte player=1){s.TryGetPlayer(player,out var p);return u.HasActivePeaceTreaty(s,p!);}
  static void Execute(GameState s){var c=Command(s);string? why=null;Check(c.IsValid(s,ref why),"native attack validity");c.Execute(s);s.Drain();}
  static string Owners(GameState s)=>string.Join("|",s.Map.Tiles.Values.Where(t=>t.unit is not null).Select(t=>$"{t.unit!.id}:{t.unit.owner}:{t.unit.type}:{t.unit.passengerUnit?.owner}"));
  public static int Run(){try{
   Test("RC001-same-commander-rogue-polytar-hits-rogue-spy",()=>{var s=Make();string before=Owners(s);var frame=NativeGameStateEnvelope.Get(s);Execute(s);Check(Unit(s,2).health==70&&Unit(s,1).health==100,"true weapon damage and attackless Spy retaliation");Check(Harness.Battles==1&&Unit(s,1).moved&&Unit(s,1).attacked,"native battle and spending once");Check(Owners(s)==before&&ReferenceEquals(frame,NativeGameStateEnvelope.Get(s)),"no ownership/type/ledger query mutation");Check(Harness.DiplomacyCalls==0,"rogue attack deniable");});
   foreach(var pair in new[]{(true,false,(byte)1),(false,true,(byte)1),(true,false,(byte)2),(true,true,(byte)2)})Test($"RC-pair-{pair}",()=>{var s=Make(pair.Item1,pair.Item2,pair.Item3);Execute(s);Check(Unit(s,2).health==70,"all Rogue-related physical targets damaged");});
   Test("RC-normal-friendly-remains-protected",()=>{var s=Make(false,false);var c=Command(s);string? e=null;Check(!c.IsValid(s,ref e),"ordinary friendly target absent");NativeRogueRules.BeforeAttack(c,s,out var scope);try{Check(Protection(s,Unit(s,2)),"direct invalid command receives no exception");}finally{NativeRogueRules.AttackFinished(null,scope);}});
   Test("RC-normal-enemy-native-diplomacy",()=>{var s=Make(false,false,2);Execute(s);Check(Unit(s,2).health==70&&Harness.DiplomacyCalls==1,"ordinary combat unchanged");});
   foreach(bool rogue in new[]{true,false})Test("RC-treaty-"+rogue,()=>{var s=Make(rogue,false,2);s.TryGetPlayer(1,out var p);p!.Treaty=true;var c=Command(s);string? e=null;Check(c.IsValid(s,ref e)==rogue,"treaty waived only for Rogue source");if(rogue){c.Execute(s);s.Drain();Check(Unit(s,2).health==70&&p.Treaty&&Harness.DiplomacyCalls==0,"real damage without breaking treaty");}});
   Test("RC-armed-rogue-retaliates-same-commander",()=>{var s=Make();var v=Unit(s,2);v.type=UnitType.warrior;v.UnitData.attack=20;v.UnitData.defence=20;Execute(s);Check(v.health==70&&Unit(s,1).health==80,"both native strike and retaliation occur");});
   foreach(string block in new[]{"range","frozen","fog"})Test("RC-retaliation-native-"+block,()=>{var s=Make(true,true,block=="fog"?(byte)2:(byte)1);var v=Unit(s,2);v.type=UnitType.warrior;v.UnitData.attack=20;v.UnitData.defence=20;if(block=="range")v.UnitData.range=0;if(block=="frozen")v.effects.Add(UnitEffect.Frozen);if(block=="fog")Tile(s,1,1).explorers.Remove(v.owner);Execute(s);Check(Unit(s,1).health==100,"no extra retaliation permission");});
   foreach(string hidden in new[]{"fog","invisible"})Test("RC-hidden-target-"+hidden,()=>{var s=Make();if(hidden=="fog")Tile(s,2,1).explorers.Remove(1);else Unit(s,2).effects.Add(UnitEffect.Invisible);var c=Command(s);string? why=null;Check(!c.IsValid(s,ref why),"target hidden to commanding player");});
   foreach(string invalid in new[]{"moved","attacked","frozen","dead","wrong-actor","wrong-id","ended","unbound"})Test("RC-no-privilege-"+invalid,()=>{var s=Make();var c=Command(s);var u=Unit(s,1);if(invalid=="moved")u.moved=true;if(invalid=="attacked")u.attacked=true;if(invalid=="frozen")u.effects.Add(UnitEffect.Frozen);if(invalid=="dead")u.health=0;if(invalid=="wrong-actor")c.PlayerId=2;if(invalid=="wrong-id")c.UnitId=77;if(invalid=="ended")s.CurrentState=GameState.State.Ended;if(invalid=="unbound")NativeRegroupSession.Owned.Remove(s);NativeRogueRules.BeforeAttack(c,s,out var scope);try{Check(Protection(s,Unit(s,2))&&NativeRogueRules.Diplomacy(),"invalid command cannot bypass protection");}finally{NativeRogueRules.AttackFinished(null,scope);}});
   foreach(string stale in new[]{"turn","player","map","source","owner","epoch","retire","clear"})Test("RC-scope-revocation-"+stale,()=>{var s=Make();var target=Unit(s,2);var c=Command(s);NativeRogueRules.BeforeAttack(c,s,out var scope);Check(!Protection(s,target),"initial exact command admitted");if(stale=="turn")s.CurrentTurn++;if(stale=="player")s.CurrentPlayer=2;if(stale=="map")s.Map=new();if(stale=="source")Tile(s,1,1).unit=new(){id=1,owner=1,coordinates=new(1,1)};if(stale=="owner")Unit(s,1).owner=2;if(stale=="epoch")Write(s,Read(s) with{Epoch=Guid.NewGuid()});if(stale=="retire")NativeRegroupSession.Owned.Remove(s);if(stale=="clear")NativeRogueRules.Clear();Check(Protection(s,target)&&NativeRogueRules.Diplomacy(),"stale context grants no exception");NativeRogueRules.AttackFinished(null,scope);Check(Protection(s,target),"late finalizer cannot revive context");});
   Test("RC-ordinary-source-exempts-only-individual-rogue",()=>{var s=Make(false,true);NativeRogueRules.BeforeAttack(Command(s),s,out var scope);try{Check(!Protection(s,Unit(s,2))&&Protection(s,Unit(s,3))&&Protection(s,Unit(s,1)),"no same-faction-wide exemption");}finally{NativeRogueRules.AttackFinished(null,scope);}});
   Test("RC-rogue-native-splash-neighbor-remains-targetable",()=>{var s=Make();NativeRogueRules.BeforeAttack(Command(s),s,out var scope);try{Check(!Protection(s,Unit(s,3))&&Protection(s,Unit(s,1)),"source Rogue hostile to other bodies, never itself");}finally{NativeRogueRules.AttackFinished(null,scope);}});
   Test("RC-unrelated-state-player-body-queries-unchanged",()=>{var s=Make();var other=Make(false,false);NativeRogueRules.BeforeAttack(Command(s),s,out var scope);try{Check(Protection(other,Unit(other,2)),"other state fenced");Check(Protection(s,new UnitState{owner=1,coordinates=new(2,1)}),"detached target cannot borrow scope");s.TryGetPlayer(2,out var p);p!.Treaty=true;Check(Unit(s,2).HasActivePeaceTreaty(s,p),"wrong player query untouched");}finally{NativeRogueRules.AttackFinished(null,scope);}});
   Test("RC-nested-unrelated-query-fences-restores-and-error",()=>{var s=Make();NativeRogueRules.BeforeAttack(Command(s),s,out var outer);var invalid=new AttackAction{Origin=Unit(s,3).coordinates,Target=Unit(s,2).coordinates};NativeRogueRules.BeforeAttack(invalid,s,out var inner);Check(Protection(s,Unit(s,2))&&NativeRogueRules.Diplomacy(),"unqueued nested action fences outer");var e=new Exception();Check(ReferenceEquals(e,NativeRogueRules.AttackFinished(e,inner))&&!Protection(s,Unit(s,2)),"nested error restores exact outer");NativeRogueRules.AttackFinished(null,inner);Check(!Protection(s,Unit(s,2)),"duplicate inner finalizer harmless");NativeRogueRules.AttackFinished(null,outer);Check(Protection(s,Unit(s,2))&&NativeRogueRules.Diplomacy(),"outer closes");});
   Test("RC-queued-action-scope-only-while-queued",()=>{var s=Make();var a=new AttackAction{Origin=Unit(s,1).coordinates,Target=Unit(s,2).coordinates};s.ActionStack.Add(a);NativeRogueRules.BeforeAttack(a,s,out var scope);Check(!NativeRogueRules.Diplomacy(),"exact native queued Rogue source has deniability");NativeRogueRules.AttackFinished(null,scope);s.ActionStack.Remove(a);NativeRogueRules.BeforeAttack(a,s,out var denied);Check(NativeRogueRules.Diplomacy(),"detached action does not acquire scope");NativeRogueRules.AttackFinished(null,denied);});
   Test("RC-native-command-error-cleans-scope",()=>{var s=Make();Harness.ThrowCommand=true;try{Command(s).Execute(s);throw new Exception("expected failure");}catch(Exception e){Check(e.Message=="native command error","original error preserved");}Check(Protection(s,Unit(s,2))&&NativeRogueRules.Diplomacy()&&!Unit(s,1).attacked,"no stale privilege/action mutation");});
   Test("RC-lethal-rogue-score-owner-and-physical-kill",()=>{var s=Make();var u=Unit(s,1);var v=Unit(s,2);v.health=20;v.passengerUnit=new(){id=9,owner=v.owner};string own=Owners(s);Execute(s);Check(!s.TryGetUnit(2,out _)&&u.kills==1,"victim removed once with true killer count");Check(v.owner==1&&v.passengerUnit.owner==1&&u.owner==1,"temporary death accounting owners restored");Check(NativeRogueRules.RememberedOwner(s,u)==2,"surviving Rogue permanent owner retained");});
   Test("RC-persist-followup-native-budget",()=>{var s=Make();Unit(s,1).Abilities.Add(Ability.Persist);Unit(s,2).health=20;Execute(s);Check(Unit(s,1).kills==1&&!Unit(s,1).attacked&&Unit(s,1).moved,"native kill followup remains without fresh movement");});
   Test("RC-casualty-count-uses-permanent-owner",()=>{var s=Make();Unit(s,2).health=20;s.TryGetPlayer(1,out var commander);s.TryGetPlayer(3,out var owner);commander!.casualities=5;owner!.casualities=8;Execute(s);Check(commander.casualities==5&&owner.casualities==9&&commander.KillCount==1,"paired casualty total moves to permanent victim owner, killer stays commander");});
   Test("RC-nonlethal-no-casualty-adjustment",()=>{var s=Make();Execute(s);Check(Native.Items(s.PlayerStates).Cast<PlayerState>().Sum(p=>(long)p.casualities)==0,"nonlethal native result untouched");});
   Test("RC-ordinary-victim-keeps-native-casualty",()=>{var s=Make(true,false);Unit(s,2).health=20;Execute(s);s.TryGetPlayer(1,out var commander);s.TryGetPlayer(3,out var unrelated);Check(commander!.casualities==1&&unrelated!.casualities==0,"ordinary victim attributed normally");});
   Test("RC-casualty-postfix-noop-error-and-duplicate",()=>{var s=Make();var v=Unit(s,2);NativeRogueAccounting.BeforeDamage(s,v.coordinates,100,out var scope);s.TryGetPlayer(1,out var commander);s.TryGetPlayer(3,out var owner);v.health=0;commander!.casualities=1;NativeRogueAccounting.AfterDamage(scope,false);Check(commander.casualities==1&&owner!.casualities==0,"skipped original not corrected");NativeRogueAccounting.AfterDamage(scope,true);NativeRogueAccounting.AfterDamage(scope,true);Check(commander.casualities==0&&owner!.casualities==1,"exact completed increment transferred once");});
   Test("RC-casualty-partial-setter-rollback",()=>{var s=Make();var v=Unit(s,2);NativeRogueAccounting.BeforeDamage(s,v.coordinates,100,out var scope);s.TryGetPlayer(1,out var commander);s.TryGetPlayer(3,out var owner);v.health=0;commander!.casualities=1;Harness.FailCasualtyOwner=3;try{NativeRogueAccounting.AfterDamage(scope,true);throw new Exception("expected");}catch(Exception e){Check(e.GetBaseException().Message=="casualty setter failed","setter error propagated");}Check(commander.casualities==1&&owner!.casualities==0,"native pre-correction pair restored on write error");});
   foreach(string stale in new[]{"epoch","unbound","removed"})Test("RC-casualty-stale-"+stale,()=>{var s=Make();var v=Unit(s,2);NativeRogueAccounting.BeforeDamage(s,v.coordinates,100,out var scope);s.TryGetPlayer(1,out var commander);s.TryGetPlayer(3,out var owner);v.health=0;commander!.casualities=1;if(stale=="epoch")Write(s,Read(s) with{Epoch=Guid.NewGuid()});if(stale=="unbound")NativeRegroupSession.Owned.Remove(s);if(stale=="removed")Tile(s,2,1).unit=null;NativeRogueAccounting.AfterDamage(scope,true);Check(commander.casualities==1&&owner!.casualities==0,"stale callback cannot redirect statistics");});
   Test("RC-registers-safe-reference-predicate",()=>{var h=new HarmonyLib.Harmony();NativeRogueRules.Install(h);Check(h.Hooks.Contains("UnitState.HasActivePeaceTreaty"),"native early relation hook installed");Check(!h.Hooks.Any(x=>x.Contains("IsAllowedToFinish")),"no wrapped value ABI hook");});
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Tests.Count,assertions=Assertions,tests=Tests,nativeGame="NOT RUN; native-shaped managed boundary"}));return 0;
  }catch(Exception e){Console.WriteLine(e);return 1;}finally{NativeRogueRules.Clear();}}
 }
}
